package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class HudFrameTest {public static void main(String[] args)throws Exception{Path fixtures=Paths.get(args[0]);int checks=0,frames=0;try(DirectoryStream<Path> entries=Files.newDirectoryStream(fixtures,"*.nab")){for(Path entry:entries){String name=entry.getFileName().toString().replace(".nab","");byte[] input=Files.readAllBytes(fixtures.resolve(name+".nab")),before=input.clone(),golden=Files.readAllBytes(fixtures.resolve(name+".hud"));NativeHudFrame frame=new NativeHudFrame(new NativeSceneSnapshot(input));if(!Arrays.equals(input,before))throw new AssertionError("Input mutation");ByteBuffer expected=ByteBuffer.wrap(golden).order(ByteOrder.LITTLE_ENDIAN);for(ByteBuffer plane:new ByteBuffer[]{frame.colors(),frame.metadata()}){if(!plane.isDirect()||!plane.isReadOnly()||plane.remaining()!=153600)throw new AssertionError("Plane ownership");while(plane.hasRemaining()){if(plane.get()!=expected.get())throw new AssertionError("HUD plane "+name+" byte "+expected.position());checks++;}}for(int y=0;y<160;y++){int[] p=frame.parameters(y);for(int v:p){if(v!=expected.getInt())throw new AssertionError("Row effect "+name+" y="+y);checks++;}p[0]^=1;if(p[0]==frame.parameters(y)[0])throw new AssertionError("Borrowed parameters");}if(expected.hasRemaining())throw new AssertionError("Trailing reference");frames++;}}System.out.println("PASS_HUD_FRAME frames="+frames+" exact_checks="+checks+" row_owned=true direct_readonly_planes=true");}}
